  const log = { info() {}, warn() {}, error() {} };
  const g = globalThis;
  const realFetch = g.fetch;
  g.fetch = async (/** @type {any} */ u) => {
    urls.push(String(u));
    return { ok: true, status: 200, json: async () => ({ results: [] }) };
